import * as T from 'three';
// Small deterministic surface maps; no downloads or layout changes.
const maps=new Map();
function surface(kind){if(maps.has(kind))return maps.get(kind);const n=256,data=new Uint8Array(n*n*4);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const noise=Math.sin(x*127.1+y*311.7)*43758.5453%1;let v=238;if(kind==='wood')v=222+16*Math.sin(x*.36+2*Math.sin(y*.025)+Math.sin(x*.06))+6*noise;else if(kind==='marble')v=65+135*Math.pow(Math.max(0,Math.sin(x*.038+y*.025+1.5*Math.sin(y*.04))),24)+5*noise;else if(kind==='fabric')v=226+12*Math.sin(x*Math.PI/2)*Math.sin(y*Math.PI/2)+6*noise;else v=236+10*noise;const i=(y*n+x)*4;data[i]=data[i+1]=data[i+2]=Math.max(0,Math.min(255,v));data[i+3]=255;}const t=new T.DataTexture(data,n,n);t.wrapS=t.wrapT=T.RepeatWrapping;t.magFilter=T.LinearFilter;t.minFilter=T.LinearMipmapLinearFilter;t.generateMipmaps=true;t.needsUpdate=true;t.repeat.set(kind==='wood'?2:kind==='marble'?1:12,kind==='wood'?1:kind==='marble'?1:12);t.userData.shared=true;maps.set(kind,t);return t;}
export function finish(mat,kind){mat.map=surface(kind);mat.bumpMap=surface(kind);mat.bumpScale=kind==='wood'?.002:kind==='marble'?.0003:.001;mat.roughness=kind==='leather'?.48:kind==='wood'?.55:kind==='marble'?.24:.92;return mat;}
export function bevelBox(w,h,d,r=.008){r=Math.min(r,w/4,h/4,d/4);const s=new T.Shape();s.moveTo(-w/2+r,-h/2+r);s.lineTo(w/2-r,-h/2+r);s.lineTo(w/2-r,h/2-r);s.lineTo(-w/2+r,h/2-r);s.closePath();const g=new T.ExtrudeGeometry(s,{depth:d-2*r,bevelEnabled:true,bevelSegments:3,bevelSize:r,bevelThickness:r,steps:1});g.translate(0,0,-d/2+r);return g;}
